  ('timesofindia', 'Times of India', 'Scientists claim Moon is drifting away from Earth at 3.8 centimetres a year. What will happen to the planet as it goes further?', 'https://timesofindia.indiatimes.com/science/moon-is-drifting-away-from-earth-at-3-8-centimetres-a-year-what-will-happen-to-the-planet-as-it-goes-further/articleshow/132573201.cms', 'The Moon is gradually distancing itself from Earth, which has significant implications for our planet. Over millions of years, this migration will result in extended daylight hours and the end of total solar eclipses. Furthermore, the weakened tides will disrupt coastal ecosystems and marine life. As the Moon ascends to a higher orbit, E', '2026-07-23 06:20:56+00', 'Read-only reference import: public source metadata only. No original body text, embeddings, entities, claims, or relationship data were copied.', '[]'::jsonb, false, false, false, 'v2-original-reference-news-2026-08-19', 'active', 'Copied only from the original platform’s public article metadata in a read-only reference pass; source URL retained for verification. No original database relationship or private metadata was imported.'),
  ('bbc-world', 'BBC', 'Russia''s businesses under strain from Ukraine''s attacks on Wildberries', 'https://www.bbc.co.uk/news/articles/cvg9n2y61w6o?at_medium=RSS&amp;at_campaign=rss', 'Ukrainian drones have hit several retail warehouses belonging to Russia''s biggest online retailer Wildberries in a matter of days.', '2026-07-23 06:15:35+00', 'Read-only reference import: public source metadata only. No original body text, embeddings, entities, claims, or relationship data were copied.', '[]'::jsonb, false, false, false, 'v2-original-reference-news-2026-08-19', 'active', 'Copied only from the original platform’s public article metadata in a read-only reference pass; source URL retained for verification. No original database relationship or private metadata was imported.'),
